<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\RequestInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\OidcFlowContext;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\RequestObjectValidator;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\OAuth\Authentication\Application\SessionManager;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\OidcCookieManager;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\OidcResponseBuilder;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\OidcUrlBuilder;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ValueObject\PkceChallenge;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\OAuth\Par\Application\Usecase\ResolveParRequest\ResolveParRequestUsecase;
use Civi\Lughauth\Features\OAuth\Par\Domain\Exception\ParException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use OpenApi\Attributes as OA;

/**
 * HTTP driver for the OIDC Authorization Endpoint, handling the interactive HTML login flow.
 *
 * This class is responsible for presenting and processing the browser-facing authorization UI
 * that implements RFC 6749 / OpenID Connect Core. It covers three main concerns: initiating
 * the authorization flow (GET /authorize), processing each incremental login step submitted
 * by the user (POST /authorize), and resuming an already-active session without re-prompting
 * the user for credentials (check-session/refresh endpoint).
 *
 * The class resolves PAR (Pushed Authorization Request) URIs and signed request objects before
 * building the flow context, validates PKCE challenges, delegates step rendering and
 * authentication to OidcStepRouter, and emits the final redirect with the authorization code
 * (or tokens) once all challenges have been satisfied. Cookies for both the pre-session state
 * and the authenticated session are managed via OidcCookieManager.
 *
 * Relationships: depends on AuthenticateUser (domain service), SessionManager, OidcStepRouter
 * (step dispatch), OidcResponseBuilder (redirect construction), HtmlSecurer (CSRF token
 * verification), and DecorateHtml (themed page wrapping).
 */
class AuthorizeHtml
{
    use LoggerAwareTrait;

    public function __construct(
        private readonly Context $context,
        private readonly ClientStoreGateway $clients,
        private readonly SessionManager $sessions,
        private readonly AuthenticateUser $authenticator,
        private readonly HtmlSecurer $securer,
        private readonly DecorateHtml  $decorator,
        private readonly OidcResponseBuilder $responseBuilder,
        private readonly OidcCookieManager $cookies,
        private readonly OidcUrlBuilder $urlBuilder,
        private readonly OidcStepRouter $router,
        private readonly ResolveParRequestUsecase $resolveParRequest,
        private readonly RequestObjectValidator $requestObjectValidator,
    ) {
    }


    #[OA\Get(
        path: '/oauth/openid/{tenant}/authorize',
        summary: 'Authorization Endpoint — interactive login UI',
        description: 'Returns the HTML login form. Clients must redirect the user-agent here to initiate the Authorization Code flow with PKCE.',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'response_type', in: 'query', required: true, schema: new OA\Schema(type: 'string', example: 'code')),
            new OA\Parameter(name: 'client_id', in: 'query', required: true, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'redirect_uri', in: 'query', required: true, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'scope', in: 'query', required: true, schema: new OA\Schema(type: 'string', example: 'openid email profile')),
            new OA\Parameter(name: 'code_challenge', in: 'query', required: true, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'code_challenge_method', in: 'query', required: false, schema: new OA\Schema(type: 'string', enum: ['S256', 'plain'])),
            new OA\Parameter(name: 'state', in: 'query', required: false, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'nonce', in: 'query', required: false, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'prompt', in: 'query', required: false, schema: new OA\Schema(type: 'string', enum: ['none', 'login', 'consent', 'select_account'])),
        ],
        responses: [
            new OA\Response(response: 200, description: 'HTML login form'),
            new OA\Response(response: 302, description: 'Redirect with authorization code (if session already active)'),
        ]
    )]
    /**
     * Handles the initial GET request to the authorization endpoint.
     *
     * Validates the client, resolves PAR or request-object overrides, and either resumes an
     * existing session silently or renders the first login step. When prompt=none and no
     * active session exists, it immediately redirects with an error.
     */
    public function authorize(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $flow = $this->buildContext($request, $tenant);
        $this->logDebug('OIDC authorize enter', [
            'tenant' => $tenant,
            'clientId' => $flow->clientId,
            'prompt' => $flow->prompt,
            'sessionId' => (string) ($flow->sessionId ?? ''),
            'state' => $flow->state,
            'nonce' => $flow->nonce,
        ]);
        $client = $this->verifyClient($flow->clientId, $tenant, $flow->redirect, $flow->scope);
        $pkceError = $this->requirePkce($flow, $response);
        if ($pkceError !== null) {
            return $pkceError;
        }
        $authRequest = $this->buildAuthRequest($flow, $client);
        $sess = $this->sessions->loadSession($flow->sessionId ?? '', $flow->nonce, $flow->state);
        $this->logDebug('OIDC authorize session lookup', [
            'tenant' => $tenant,
            'sessionId' => (string) ($flow->sessionId ?? ''),
            'sessionFound' => $sess ? 'true' : 'false',
        ]);
        if ($sess) {
            return $this->cisdPage($request, $response, $flow, $authRequest);
        } elseif ("none" === $flow->prompt) {
            return $this->redirectError($tenant, $flow->redirect, 'No session', $response);
        } else {
            $input = $this->buildStepInput($flow, $request, $authRequest, new ChallengesState(), []);
            try {
                return $this->renderStep(null, null, $input, $response, null, $input->challenges);
            } catch (LoginException $ex) {
                if ($ex->auth->error === AuthenticationResult::ERR_UNKNOW_USER) {
                    return $this->renderNotFound($tenant, $flow->locale, $request, $response);
                }
                throw $ex;
            }
        }
    }

    /**
     * Handles the check-session POST that resumes an authenticated session silently.
     *
     * Verifies the CSRF token (csid), reloads the session, and immediately completes
     * the authorization flow without showing any login UI. If the session has expired
     * or the csid is invalid, the user is redirected back to the login form.
     *
     * When sessionAuthenticated requires an intermediate step (e.g. terms consent), the step
     * form is rendered WITHOUT clearing the session cookie so subsequent submissions come back
     * here and are dispatched to the correct step handler via runSessionStep().
     */
    public function refresh(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $body = (array) ($request->getParsedBody() ?? []);
        $tenant = $args['tenant'];
        $flow = $this->buildContext($request, $tenant);
        $this->logDebug('OIDC check-session enter', [
            'tenant' => $tenant,
            'clientId' => $flow->clientId,
            'prompt' => $flow->prompt,
            'sessionId' => (string) ($flow->sessionId ?? ''),
            'hasCsid' => isset($body['csid']) ? 'true' : 'false',
            'state' => $flow->state,
            'nonce' => $flow->nonce,
        ]);
        $client = $this->verifyClient($flow->clientId, $tenant, $flow->redirect, $flow->scope);
        $pkceError = $this->requirePkce($flow, $response);
        if ($pkceError !== null) {
            return $pkceError;
        }
        $authRequest = $this->buildAuthRequest($flow, $client);
        $csid = $this->securer->verifyToken($body['csid'] ?? '');
        if ($csid === null) {
            $this->logWarning('OIDC check-session invalid csid', [
                'tenant' => $tenant,
                'sessionId' => (string) ($flow->sessionId ?? ''),
            ]);
            return $this->redirectToLogin($response, $flow, $authRequest);
        }
        $sess = $this->sessions->loadSession($flow->sessionId ?? '', $flow->nonce, $flow->state);
        if ($sess) {
            $this->logDebug('OIDC check-session session loaded', [
                'tenant' => $tenant,
                'sessionId' => (string) ($flow->sessionId ?? ''),
                'sessionUserId' => $sess->userId,
                'sessionClientId' => $sess->clientId,
            ]);
            $challenges = (new ChallengesState())
                ->withUsername($sess->userId)
                ->withMfa($sess->withMfa)
                ->withSession(true);
            $input = $this->buildStepInput($flow, $request, $authRequest, $challenges, $body);
            $step = $body['step'] ?? null;
            if ($step !== null && $step !== '') {
                return $this->runSessionStep($step, $csid, $tenant, $flow, $client, $authRequest, $input, $request, $response);
            }
            try {
                $auth = $this->authenticator->sessionAuthenticated(
                    $authRequest,
                    $challenges,
                    $tenant,
                    $flow->issuer,
                    $sess->csid,
                    $flow->sessionId ?? '',
                    $flow->state,
                    $flow->nonce
                );
                return $this->responseBuilder->buildSuccessRedirect($flow, $auth, $client, $authRequest, $response);
            } catch (LoginException $ex) {
                // Render the step form (e.g. consent) but keep the session cookie intact so the
                // user's next submission hits this same endpoint with the session still valid.
                $result = $this->executeStep($input, $response, $ex->auth, null, null);
                if ($result->type !== StepResult::TYPE_RENDER || !$result->response) {
                    throw new UnauthorizedException();
                }
                return $result->response;
            }
        } else {
            $this->logWarning('OIDC check-session missing session', [
                'tenant' => $tenant,
                'sessionId' => (string) ($flow->sessionId ?? ''),
            ]);
            return $this->redirectToLogin($response, $flow, $authRequest);
        }
    }

    private function runSessionStep(
        string $step,
        string $csid,
        string $tenant,
        OidcFlowContext $flow,
        ClientData $client,
        AuthenticationRequest $authRequest,
        StepInput $input,
        ServerRequestInterface $request,
        ResponseInterface $response
    ): ResponseInterface {
        try {
            $result = $this->executeStep($input, $response, null, $step, $csid);
            if ($result->type === StepResult::TYPE_PROCEED && $result->authResponse) {
                return $this->responseBuilder->buildSuccessRedirect($flow, $result->authResponse, $client, $authRequest, $response);
            }
            if ($result->type === StepResult::TYPE_RENDER && $result->response) {
                return $result->response;
            }
            throw new UnauthorizedException();
        } catch (LoginException $ex) {
            $isConsentStep = in_array($ex->auth->error, [
                AuthenticationResult::ERR_CONSENT_REQUIRED,
                AuthenticationResult::ERR_SCOPES_CONSENT_REQUIRED,
            ], true);
            if ($isConsentStep) {
                // Consent was stored but the current DB snapshot (REPEATABLE READ) doesn't reflect
                // the write yet. Redirect to GET /authorize so a fresh DB connection picks it up.
                $url = $this->urlBuilder->authorizeUrl($authRequest, $tenant, $flow->state, $flow->nonce, array_filter([
                    'prompt' => $flow->prompt,
                    'code_challenge' => $flow->codeChallenge,
                    'code_challenge_method' => $flow->codeChallengeMethod,
                ]));
                return $response->withStatus(302)->withHeader('Location', $url);
            }
            return $this->renderSessionError($tenant, $flow->locale, $flow->redirect, $flow->state, $ex->auth->error ?? 'access_denied', $ex->getMessage(), $request, $response);
        } catch (UnauthorizedException $ex) {
            return $this->renderSessionError($tenant, $flow->locale, $flow->redirect, $flow->state, 'access_denied', $ex->getMessage(), $request, $response);
        }
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/authorize',
        summary: 'Authorization Endpoint — form submission',
        description: 'Processes login form submissions (credentials, MFA steps). Not intended for direct API calls; called by the browser during the interactive login flow.',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        requestBody: new OA\RequestBody(
            content: new OA\MediaType(
                mediaType: 'application/x-www-form-urlencoded',
                schema: new OA\Schema(properties: [
                    new OA\Property(property: 'step', type: 'string', description: 'Current login step'),
                    new OA\Property(property: 'username', type: 'string'),
                    new OA\Property(property: 'password', type: 'string'),
                    new OA\Property(property: 'csid', type: 'string', description: 'Cross-site ID token'),
                ])
            )
        ),
        responses: [
            new OA\Response(response: 302, description: 'Redirect with authorization code on successful login'),
            new OA\Response(response: 200, description: 'HTML form for next login step or error'),
        ]
    )]
    /**
     * Handles form POST submissions at each step of the interactive login flow.
     *
     * Reads the current step and pre-session cookie, executes the appropriate step handler
     * (credential check, MFA, consent, etc.), and either redirects with an authorization code
     * on success or re-renders the step with an error message on failure.
     */
    public function formAuthorize(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $body = (array) ($request->getParsedBody() ?? []);
        $tenant = $args['tenant'];
        $flow = $this->buildContext($request, $tenant);
        $client = $this->verifyClient($flow->clientId, $tenant, $flow->redirect, $flow->scope);
        $pkceError = $this->requirePkce($flow, $response);
        if ($pkceError !== null) {
            return $pkceError;
        }
        $clientRequest = $this->buildAuthRequest($flow, $client);
        $state = new ChallengesState();
        if ($flow->preSessionId !== null && $flow->preSessionId !== '') {
            $state = $this->cookies->loadPreSessionChallenges($tenant, $flow->preSessionId);
        }
        $step = $body['step'] ?? null;
        $input = $this->buildStepInput($flow, $request, $clientRequest, $state, $body);
        try {
            // Tengo que sacar la password de fuera
            $csid = null;
            if (isset($body['csid'])) {
                $csid = $this->securer->verifyToken($body['csid']);
                if ($csid === null) {
                    throw new UnauthorizedException('missingin_csid');
                }
            }

            $result = $this->executeStep($input, $response, null, $step, $csid);
            if ($result->type === StepResult::TYPE_PROCEED && $result->authResponse) {
                return $this->responseBuilder->buildSuccessRedirect($flow, $result->authResponse, $client, $clientRequest, $response);
            }
            if ($result->type === StepResult::TYPE_RENDER && $result->response) {
                $response = $this->cookies->clearSession($result->response, $tenant);
                $cookie = $this->cookies->storePreSession($flow, $result->challenges);
                return $cookie->attach($response);
            }

            throw new UnauthorizedException();
        } catch (LoginException $ex) {
            $isRecoverableStep = in_array($ex->auth->error, [
                AuthenticationResult::ERR_CONSENT_REQUIRED,
                AuthenticationResult::ERR_SCOPES_CONSENT_REQUIRED,
            ], true);
            if ($state->session && !$isRecoverableStep) {
                return $this->renderSessionError($tenant, $flow->locale, $flow->redirect, $flow->state, $ex->auth->error ?? 'access_denied', $ex->getMessage(), $request, $response);
            }
            return $this->renderStep($ex->getMessage(), $ex->auth, $input, $response, null, $ex->challenges ?? $state);
        } catch (UnauthorizedException $ex) {
            if ($state->session) {
                return $this->renderSessionError($tenant, $flow->locale, $flow->redirect, $flow->state, 'access_denied', $ex->getMessage(), $request, $response);
            }
            return $this->renderStep($ex->getMessage(), null, $input, $response, null, $state);
        }
    }

    private function requirePkce(OidcFlowContext $flow, ResponseInterface $response): ?ResponseInterface
    {
        if ($flow->codeChallenge === null) {
            return $this->redirectError($flow->tenant, $flow->redirect, 'invalid_request', $response);
        }
        try {
            PkceChallenge::fromRequest($flow->codeChallenge, $flow->codeChallengeMethod);
        } catch (\InvalidArgumentException) {
            return $this->redirectError($flow->tenant, $flow->redirect, 'invalid_request', $response);
        }
        return null;
    }

    private function buildContext(ServerRequestInterface $request, string $tenant): OidcFlowContext
    {
        $query = $request->getQueryParams();
        if (isset($query['request_uri']) && $query['request_uri'] !== '') {
            try {
                $parRequest = $this->resolveParRequest->resolve((string) $query['request_uri'], $tenant);
            } catch (ParException) {
                throw new UnauthorizedException('invalid_request_uri');
            }
            $request = $request->withQueryParams(array_merge($parRequest->params, $query));
            $query = $request->getQueryParams();
        }

        if (isset($query['request']) && $query['request'] !== '') {
            $clientId = (string) ($query['client_id'] ?? '');
            if ($clientId === '') {
                throw new UnauthorizedException('invalid_request_object');
            }
            $client = $this->clients->preValidatedClient($clientId);
            if ($client === null) {
                throw new UnauthorizedException('invalid_request_object');
            }
            try {
                $verifiedParams = $this->requestObjectValidator->validate((string) $query['request'], $client);
            } catch (\InvalidArgumentException) {
                throw new UnauthorizedException('invalid_request_object');
            }
            $query = array_merge($query, $verifiedParams);
            $request = $request->withQueryParams($query);
        }
        return OidcFlowContext::fromRequest($request, $tenant, $this->context);
    }

    private function buildAuthRequest(OidcFlowContext $flow, ClientData $client): AuthenticationRequest
    {
        return new AuthenticationRequest(
            client: $client,
            scope: $flow->scope,
            redirect: $flow->redirect,
            responseType: $flow->responseType,
            audiences: array_values(array_unique([$flow->clientId, ...$flow->audiences]))
        );
    }

    private function verifyClient(string $clientId, string $tenant, string $redirect, string $scope): ClientData
    {
        $client = $this->clients->publicClientData($clientId, $tenant, $redirect, $scope);
        if (!$client) {
            throw new UnauthorizedException('Client not allowed');
        } else {
            return $client;
        }
    }

    private function redirectError(string $tenant, string $redirect, string $error, ResponseInterface $response): ResponseInterface
    {
        $this->logWarning('OIDC redirect error', [
            'tenant' => $tenant,
            'redirect' => $redirect,
            'error' => $error,
        ]);
        $response = $response->withStatus(302)->withHeader('Location', $redirect . '#error=' . urlencode($error));
        return $this->cookies->clearSession($response, $tenant);
    }

    private function renderStep(?string $message, ?AuthenticationResult $error, StepInput $input, ResponseInterface $response, ?string $stepOverride, ?ChallengesState $challengesOverride): ResponseInterface
    {
        $error = $error === null && $message !== null && $message !== ''
            ? new AuthenticationResult(valid: false, errorMessage: $message)
            : $error;
        $step = $error ? null : ($stepOverride ?? ($input->request->getQueryParams()['step'] ?? null));
        if ($challengesOverride !== null) {
            $input = new StepInput(
                context: $input->context,
                authRequest: $input->authRequest,
                challenges: $challengesOverride,
                body: $input->body,
                request: $input->request
            );
        }
        $result = $this->executeStep($input, $response, $error, $step, null);
        if ($result->type !== StepResult::TYPE_RENDER || !$result->response) {
            throw new UnauthorizedException();
        }
        $response = $this->cookies->clearSession($result->response, $input->context->tenant);
        $cookie = $this->cookies->storePreSession($input->context, $result->challenges);
        return $cookie->attach($response);
    }

    private function executeStep(
        StepInput $input,
        ResponseInterface $response,
        ?AuthenticationResult $error,
        ?string $step,
        ?string $csid
    ): StepResult {
        $result = $this->router->run($input, $response, $error, $step, $csid);
        if (!$result) {
            throw new UnauthorizedException();
        }
        return $result;
    }

    private function buildStepInput(
        OidcFlowContext $flow,
        ServerRequestInterface $request,
        AuthenticationRequest $authRequest,
        ChallengesState $state,
        ?array $body
    ): StepInput {
        return new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: $state,
            body: $body ?? [],
            request: $request
        );
    }

    private function redirectToLogin(
        ResponseInterface $response,
        OidcFlowContext $flow,
        AuthenticationRequest $authRequest
    ): ResponseInterface {
        $this->logDebug('OIDC redirectToLogin', [
            'tenant' => $flow->tenant,
            'clientId' => $flow->clientId,
            'prompt' => $flow->prompt,
            'sessionId' => (string) ($flow->sessionId ?? ''),
        ]);
        if ($flow->prompt === 'none') {
            return $this->redirectError($flow->tenant, $flow->redirect, 'Only refresh from same device', $response);
        } else {
            $url = $this->urlBuilder->authorizeUrl(
                $authRequest,
                $flow->tenant,
                $flow->state,
                $flow->nonce,
                ['prompt' => $flow->prompt]
            );
            $response = $response->withStatus(302)->withHeader('Location', $url);
            return $this->cookies->clearSession($response, $flow->tenant);
        }
    }

    private function renderNotFound(string $tenant, string $locale, RequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $this->logWarning('OIDC tenant not found', ['tenant' => $tenant]);
        $response->getBody()->write(
            $this->decorator->getFullPage(
                $request,
                'Not Found',
                '<div class="error-page"><h1>404</h1><p>Tenant not found or not available.</p></div>',
                $locale,
                'index',
                null
            )
        );
        return $response->withStatus(404);
    }

    private function renderSessionError(
        string $tenant,
        string $locale,
        string $redirect,
        string $state,
        string $errorCode,
        string $errorMessage,
        RequestInterface $request,
        ResponseInterface $response
    ): ResponseInterface {
        $this->logWarning('OIDC session error page', ['tenant' => $tenant, 'error' => $errorCode]);
        $backUrl = $redirect . '?error=' . urlencode($errorCode);
        if ($state !== '') {
            $backUrl .= '&state=' . urlencode($state);
        }
        $safeMessage = htmlspecialchars($errorMessage, ENT_QUOTES);
        $safeCode = htmlspecialchars($errorCode, ENT_QUOTES);
        $backUrl = htmlspecialchars($backUrl, ENT_QUOTES);
        $response->getBody()->write(
            $this->decorator->getFullPage(
                $request,
                'Authorization Error',
                <<<HTML
                    <div class="error-page">
                        <h1>Authorization Error</h1>
                        <p><strong>{$safeCode}</strong></p>
                        <p>{$safeMessage}</p>
                        <a class="primary-button" href="{$backUrl}">Back</a>
                    </div>
                HTML,
                $locale,
                'index',
                $tenant
            )
        );
        return $response->withStatus(400);
    }

    private function cisdPage(
        RequestInterface $request,
        ResponseInterface $response,
        OidcFlowContext $flow,
        AuthenticationRequest $authRequest
    ): ResponseInterface {
        $js = $this->securer->configureScripts([
            $this->securer->addSignAndSend("sign", "refresh"),
        ]);
        $url = $this->urlBuilder->checkSessionUrl(
            $authRequest,
            $flow->tenant,
            $flow->state,
            $flow->nonce,
            [
                'prompt' => $flow->prompt,
                'code_challenge' => $flow->codeChallenge,
                'code_challenge_method' => $flow->codeChallengeMethod,
            ]
        );
        $response->getBody()->write($this->decorator->getFullPage($request, 'Mfa', $js . "<h1>Verifiy login source...</h1>"
            . "<form id=\"refresh\" action=\"".$url."\" method=\"POST\">"
            . "<input type=\"hidden\" name=\"csid\" id=\"sign\" />"
            . "<input type=\"submit\" style=\"display:none\" />"
            . "</form>", $flow->locale, 'index', $flow->tenant));
        return $response;
    }
}
